import os
import json
import re
import string
from collections import Counter
def task_func(json_dir_path, word_count):
    all_words = []
    for file in os.listdir(json_dir_path):
        if file.endswith('.json'):
            file_path = os.path.join(json_dir_path, file)
            with open(file_path, 'r') as f:
                try:
                    data = json.load(f)
                    text = data.get('text', '')
                    text = re.sub(f'[^{string.ascii_letters}0-9\s]', '', text).lower()
                    all_words.extend(text.split())
                except json.JSONDecodeError:
                    continue
    return Counter(all_words).most_common(word_count)

